def rate_limit_key():
    """Return a per-user key when authenticated, otherwise the remote address."""
    auth = request.headers.get("Authorization", "")
    if auth[:7].lower() == "bearer ":
        token = auth[7:].strip()
        if token:
            try:
                claims = decode_token(token)
                identity = claims.get("sub")
                if identity:
                    return f"user:{identity}"
            except Exception:
                pass
    return f"ip:{get_remote_address()}"


limiter = Limiter(
    key_func=rate_limit_key,
    default_limits=[RATE_LIMIT_DEFAULT],
    storage_uri=RATE_LIMIT_STORAGE_URL,
    headers_enabled=True,
    app=app,
)


@app.errorhandler(429)
def _rate_limit_exceeded(_):
    return jsonify({"error": "rate limit exceeded"}), 429


@jwt.invalid_token_loader

@app.route("/tasks", methods=["GET"])
@jwt_required()
def list_tasks():
    cursor = request.args.get("cursor")
    if cursor is not None:
        try:
            cursor = int(cursor)
        except (TypeError, ValueError):
            return jsonify({"error": "invalid cursor"}), 400

    limit = request.args.get("limit", "20")
    try:
        limit = int(limit)
    except (TypeError, ValueError):
        limit = 20
    limit = max(1, min(limit, 100))

    result = task_repo.list_by_owner_paginated(current_user_id(), cursor, limit)
    return jsonify(result)

def list_by_owner(self, owner_id):
    with self._connect() as conn:
        rows = conn.execute(
            "SELECT * FROM tasks WHERE owner_id = ? ORDER BY created_at DESC",
            (owner_id,),
        ).fetchall()
        return [dict(r) for r in rows]

def list_by_owner_paginated(self, owner_id, cursor=None, limit=20):
    with self._connect() as conn:
        total = conn.execute(
            "SELECT COUNT(*) AS c FROM tasks WHERE owner_id = ?",
            (owner_id,),
        ).fetchone()["c"]

        if cursor is None:
            rows = conn.execute(
                "SELECT * FROM tasks WHERE owner_id = ? "
                "ORDER BY id DESC LIMIT ?",
                (owner_id, limit + 1),
            ).fetchall()
        else:
            rows = conn.execute(
                "SELECT * FROM tasks WHERE owner_id = ? AND id < ? "
                "ORDER BY id DESC LIMIT ?",
                (owner_id, cursor, limit + 1),
            ).fetchall()

    has_more = len(rows) > limit
    page = rows[:limit]
    data = [dict(r) for r in page]
    next_cursor = str(page[-1]["id"]) if has_more and page else None
    return {"data": data, "next_cursor": next_cursor, "total": total}
